def slug(text):
    """Return a lowercase ASCII slug: digits kept, other runs collapsed to a hyphen."""
    lowered = text.lower()
    lowered = "".join(char if (char.isascii() and char.isalpha()) or char.isdigit() else "" for char in lowered)
    slug = re.sub(r"-+", "-", lowered)
    return slug.strip("-")
